package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*;
import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.transaction.PlatformTransactionManager; import org.springframework.transaction.support.TransactionTemplate;
import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
@SpringBootTest class LocalIdentityCreationTransactionIntegrationTest {
 @Autowired ClienteDAO clients; @Autowired AuthIdentityDAO identities; @Autowired ReauthenticationTokenDAO tokens; @Autowired LocalIdentityCreationService service; @Autowired PlatformTransactionManager transactions;
 UUID id; AuthenticatedUser user; String raw;
 @BeforeEach void setup(){Cliente c=clients.save(new Cliente("Rollback","Social","rollback-"+UUID.randomUUID()+"@test",null,"ROLE_CLIENTE",0,0,0,"","",""));id=c.getId();user=new AuthenticatedUser(id,c.getEmail(),Role.CLIENTE);identities.save(new AuthIdentity(id,Role.CLIENTE,AuthProvider.GOOGLE,"google-"+id,c.getEmail(),Instant.now()));identities.saveAndFlush(new AuthIdentity(id,Role.CLIENTE,AuthProvider.LOCAL,id.toString(),c.getEmail(),Instant.now()));new TransactionTemplate(transactions).executeWithoutResult(status->identities.findByProviderAndProviderSubject(AuthProvider.LOCAL,id.toString()).orElseThrow().deactivate());raw="reauth-"+UUID.randomUUID();tokens.saveAndFlush(new ReauthenticationToken(PasswordResetService.hash(raw),id,Role.CLIENTE,null,ReauthenticationPurpose.CREATE_LOCAL_IDENTITY,Instant.now(),Instant.now().plusSeconds(300)));}
 @Test void databaseRollbackRestoresPasswordIdentityAndTokenAfterUniqueConstraintFailure(){assertThrows(LocalIdentityAlreadyExistsException.class,()->service.create(user,new LocalIdentityCreationRequest(raw,"ValidPassword123")));Cliente reloaded=clients.findById(id).orElseThrow();assertNull(reloaded.getContrasena());assertFalse(identities.existsByUserIdAndRoleAndProviderAndActiveTrue(id,Role.CLIENTE,AuthProvider.LOCAL));assertTrue(identities.findByProviderAndProviderSubject(AuthProvider.GOOGLE,"google-"+id).orElseThrow().isActive());assertNull(tokens.findAll().stream().filter(token->token.getTokenHash().equals(PasswordResetService.hash(raw))).findFirst().orElseThrow().getConsumedAt());}
}
